/* 02 · Glassmorphism — design tokens (canonical) */
:root {
  --color-bg: #F4F4FB;
  --color-surface: #FFFFFF;
  --color-text: #111111;
  --color-text-secondary: #555555;
  --color-border: #E4E4EF;
  --color-primary: #111111;
  --color-primary-contrast: #FFFFFF;
  --color-accent: #7C3AED;
  --color-accent-contrast: #FFFFFF;
  --color-success: #16A34A;
  --color-warning: #D97706;
  --color-error: #DC2626;

  /* Vivid backdrop glass needs something to blur */
  --backdrop-gradient: linear-gradient(135deg, #6366F1 0%, #A855F7 45%, #EC4899 100%);
  --backdrop-glow-1: rgb(99 102 241 / 0.35);
  --backdrop-glow-2: rgb(236 72 153 / 0.28);

  /* Glass recipe — max 2 surfaces per view */
  --glass-bg-light: rgb(255 255 255 / 0.62);
  --glass-bg-dark: rgb(255 255 255 / 0.12);
  --glass-border: rgb(255 255 255 / 0.25);
  --glass-blur: 20px;
  --glass-saturation: 160%;
  --glass-shadow: 0 8px 32px rgb(0 0 0 / 0.12);
  --glass-filter: blur(var(--glass-blur)) saturate(var(--glass-saturation));

  --font-sans: 'Inter', system-ui, sans-serif;
  --font-display: 'Plus Jakarta Sans', 'Inter', sans-serif;
  --font-mono: 'JetBrains Mono', monospace;

  --font-size-h1: 56px;
  --font-size-h2: 40px;
  --font-size-h3: 28px;
  --font-size-h4: 22px;
  --font-size-h5: 18px;
  --font-size-h6: 16px;
  --font-size-body: 17px;
  --font-size-small: 14px;
  --font-size-label: 12px;

  --spacing-1: 4px;  --spacing-2: 8px;  --spacing-3: 12px;
  --spacing-4: 16px; --spacing-6: 24px; --spacing-8: 32px;
  --spacing-12: 48px; --spacing-16: 64px; --spacing-24: 96px;

  --radius-sm: 8px; --radius-md: 12px; --radius-lg: 16px; --radius-xl: 24px;
  --shadow-card: 0 8px 32px rgb(0 0 0 / 0.12);
  --shadow-focus: 0 0 0 3px var(--color-accent);

  --border-default: 1px solid var(--color-border);
  --border-glass: 1px solid var(--glass-border);

  --container-width: 1200px;

  --motion-fast: 150ms;
  --motion-normal: 200ms;
  --motion-slow: 400ms;
  --motion-ambient: 60s;
  --motion-ease: cubic-bezier(0.16, 1, 0.3, 1);
}

/* Glass is fragile under motion preferences — freeze ambient drift */
@media (prefers-reduced-motion: reduce) {
  :root { --motion-ambient: 0s; --motion-fast: 0ms; --motion-normal: 0ms; --motion-slow: 0ms;
}
}
[data-theme="dark"] {
  --color-bg: #0F172A;
  --color-surface: #1E293B;
  --color-text: #F8FAFC;
  --color-text-secondary: #94A3B8;
  --color-border: rgb(255 255 255 / 0.10);
  --color-primary: #F8FAFC;
  --color-primary-contrast: #0F172A;
  --glass-bg: var(--glass-bg-dark);
  --color-accent: #A78BFA;
  --color-accent-contrast: #111111;
}

/* Required usage guard */
.glass {
  background: var(--glass-bg-light);
  border: var(--border-glass);
  box-shadow: var(--glass-shadow);
  -webkit-backdrop-filter: var(--glass-filter);
  backdrop-filter: var(--glass-filter);
}
[data-theme="dark"] .glass { background: var(--glass-bg-dark); }
@supports not (backdrop-filter: blur(1px)) {
  .glass { background: var(--color-surface); border: var(--border-default); }
}

/* 03 · Liquid Glass — design tokens (canonical) */
:root {
  --color-bg: #0B1120;
  --color-surface: #141C2F;
  --color-text: #FFFFFF;
  --color-text-secondary: rgb(255 255 255 / 0.62);
  --color-border: rgb(255 255 255 / 0.12);
  --color-primary: #0A74E0;
  --color-primary-contrast: #FFFFFF;
  --color-accent: #0A74E0;
  --color-accent-contrast: #FFFFFF;
  --color-success: #30D158;
  --color-warning: #FFD60A;
  --color-error: #FF453A;

  /* Rich, moving media beneath — glass needs changing light */
  --media-mesh: radial-gradient(60% 80% at 20% 20%, rgb(14 165 233 / 0.5), transparent 60%),
                radial-gradient(50% 70% at 80% 30%, rgb(139 92 246 / 0.45), transparent 60%),
                radial-gradient(60% 60% at 50% 90%, rgb(244 114 182 / 0.35), transparent 60%),
                linear-gradient(180deg, #0B1120, #101A33);

  /* Liquid glass recipe — controls & floating chrome only */
  --lg-bg: rgb(255 255 255 / 0.14);
  --lg-border: rgb(255 255 255 / 0.22);
  --lg-blur: 14px;
  --lg-saturation: 180%;
  --lg-brightness: 1.08;
  --lg-specular: inset 0 1px 0 rgb(255 255 255 / 0.40), inset 0 -1px 0 rgb(255 255 255 / 0.06);
  --lg-shadow: 0 12px 40px rgb(0 0 0 / 0.18);
  --lg-filter: blur(var(--lg-blur)) saturate(var(--lg-saturation)) brightness(var(--lg-brightness));
  --lg-surface: rgb(255 255 255 / 0.72); /* solid fallback */

  --font-sans: 'Inter', system-ui, sans-serif;
  --font-display: 'Figtree', 'Inter', sans-serif;
  --font-mono: 'Geist Mono', 'JetBrains Mono', monospace;

  --font-size-h1: 56px;
  --font-size-h2: 40px;
  --font-size-h3: 28px;
  --font-size-h4: 22px;
  --font-size-h5: 18px;
  --font-size-h6: 16px;
  --font-size-body: 17px;
  --font-size-small: 14px;
  --font-size-label: 12px;

  --spacing-1: 4px;  --spacing-2: 8px;  --spacing-3: 12px;
  --spacing-4: 16px; --spacing-6: 24px; --spacing-8: 32px;
  --spacing-12: 48px; --spacing-16: 64px; --spacing-24: 96px;

  /* Continuous curves & capsules — the material's identity */
  --radius-sm: 12px; --radius-md: 24px; --radius-lg: 32px; --radius-pill: 999px;
  --shadow-float: var(--lg-shadow);
  --shadow-focus: 0 0 0 4px var(--color-accent);

  --border-default: 1px solid var(--color-border);

  --container-width: 1200px;

  /* Springy motion — liquid, never linear */
  --motion-fast: 200ms;
  --motion-normal: 350ms;
  --motion-slow: 500ms;
  --motion-ambient: 90s;
  --motion-ease: cubic-bezier(0.32, 0.72, 0, 1);
  --ease-out: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-spring: cubic-bezier(0.34, 1.56, 0.64, 1);
  --ease-spring-soft: cubic-bezier(0.34, 1.3, 0.5, 1);
}
[data-theme="light"] {
  --color-bg: #F5F7FA;
  --color-surface: #FFFFFF;
  --color-text: #0B1120;
  --color-text-secondary: rgb(11 17 32 / 0.6);
  --color-border: rgb(11 17 32 / 0.10);
  --lg-surface: rgb(11 17 32 / 0.72); /* dark-glass fallback on light bg */
}

/* Required usage guard */
.liquid {
  background: var(--lg-tint, rgb(255 255 255 / 0.14));
  border: 1px solid var(--lg-border);
  box-shadow: var(--lg-specular), var(--lg-shadow);
  -webkit-backdrop-filter: var(--lg-filter);
  backdrop-filter: var(--lg-filter);
}
[data-theme="light"] .liquid { --lg-tint: rgb(255 255 255 / 0.55); }
@supports not (backdrop-filter: blur(1px)) {
  .liquid { background: var(--lg-surface); }
}
@media (prefers-reduced-motion: reduce) {
  :root { --motion-ambient: 0s;
}
  * { transition-duration: 0ms !important; animation-duration: 0ms !important; }
}

